<div class="page-heading"><div><p class="eyebrow"><?= e($asset['item_name']) ?></p><h1><?= e($asset['asset_tag']) ?><span class="badge bg-blue-lt ms-3"><?= e($asset['state']) ?></span></h1><p class="text-secondary">Manufacturer serial: <?= e($asset['serial_number'] ?: 'Not recorded') ?></p></div><a href="/reports/timeline?q=<?= e($asset['asset_tag']) ?>" data-workspace class="btn btn-primary">Planning timeline</a></div>
<section class="card floating-card" data-card-key="asset-lifecycle"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">timeline</span>Complete asset lifecycle</h2><div class="card-body"><?php foreach ($events as $event): ?><div class="activity-row"><span class="activity-dot"></span><div><strong><?= e($event['state']) ?><?= $event['show_name']?' | ' . e($event['show_name']):'' ?></strong><p><?= e($event['details']) ?></p><small><?= e($event['user_name']) ?> | <?= e($event['created_at']) ?> UTC</small></div></div><?php endforeach; ?></div></section>
<section class="card floating-card" data-card-key="asset-assignments"><h2 class="floating-label">Show assignment history</h2><div class="card-body"><?php if (!$assignments): ?><p>This asset has not left the shop.</p><?php endif; ?><?php foreach ($assignments as $assignment): ?><a href="/shows/<?= e($assignment['show_id']) ?>" data-workspace class="record-row"><div><strong><?= e($assignment['show_name']) ?></strong><small>Assigned <?= e($assignment['assigned_at']) ?> | Due <?= e($assignment['return_date']) ?></small></div><span><?= e($assignment['end_reason'] ?: 'On Show') ?></span></a><?php endforeach; ?></div></section>
<?php if (App\Middleware\Permissions::allows('inventory.edit') && in_array($asset['state'],['Available','Missing'],true)): ?><section class="card floating-card" data-card-key="asset-condition"><h2 class="floating-label">Asset condition action</h2><div class="card-body"><form action="/inventory/assets/<?= e($asset['id']) ?>/action" method="post" data-ajax-form><?= csrf() ?><input type="hidden" name="action" value="<?= $asset['state']==='Missing'?'recover':'repair' ?>"><p><?= $asset['state']==='Missing'?'Confirm the missing asset was physically recovered and inspected as serviceable.':'Log a fault found in the shop. This removes the asset from availability and opens a repair ticket.' ?></p><label class="form-label">Inspection / condition notes<textarea class="form-control mb-3" name="notes" required maxlength="10000" rows="3"></textarea></label><div class="form-error" role="alert" hidden></div><button class="btn btn-primary"><?= $asset['state']==='Missing'?'Recover missing asset':'Open repair ticket' ?></button></form></div></section><?php endif; ?>
